import { Piscina } from "piscina";
const pool = new Piscina({ filename: new URL("./worker.js", import.meta.url).href,
                           maxThreads: 4 });
const digest = await pool.run({ path: "big.bin" });   // queued, loop stays free
await pool.close();                                    // drain in-flight tasks

const workers = Array.from({ length: navigator.hardwareConcurrency || 4 },
    () => new Worker(new URL("./worker.js", import.meta.url), { type: "module" }));
const run = (job) => new Promise((resolve, reject) => {
    const w = takeIdleWorker(workers);        // queue until one is free
    w.onmessage = (e) => { release(w); resolve(e.data); };
    w.onerror = (e) => { release(w); reject(e); };
    w.postMessage(job);
});
